package com.lianxibu.site.service.jobs;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.articles.*;
import com.lianxibu.site.service.content.CatalogAnalysisContentBaselineService;
import java.time.*;
import java.util.*;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;
import tools.jackson.databind.JsonNode;

/** Actual allocated original day, complete member bodies and native replacement baseline; no input is frozen here. */
public final class CatalogDayAnalysisInputPermitService {
    private record State(CatalogDayAnalysisReservationLedger.Stored receipt,CatalogDayEntityEvidenceService.Entity entity,
                         CatalogEntityAnalysisHeaderService.Header header,String target,CatalogAnalysisContentBaselineService.Baseline baseline,
                         List<String> judgments,List<String> origins){private State{judgments=List.copyOf(judgments);origins=List.copyOf(origins);}}
    public static final class Captured {
        private final Object issuer;private final CatalogDayAnalysisCommitPermitService.Captured day;private final State state;private final JdbcCatalogVersionJobFacts.Snapshot oldJobs;
        private Captured(Object issuer,CatalogDayAnalysisCommitPermitService.Captured day,State state,JdbcCatalogVersionJobFacts.Snapshot oldJobs){this.issuer=issuer;this.day=day;this.state=state;this.oldJobs=oldJobs;}
        public CatalogDayAnalysisReservationLedger.Stored receipt(){return state.receipt();}public CatalogDayEntityEvidenceService.Entity entity(){return state.entity();}public CatalogEntityAnalysisHeaderService.Header header(){return state.header();}public String targetId(){return state.target();}public CatalogAnalysisContentBaselineService.Baseline baseline(){return state.baseline();}public CatalogDayEntityEvidenceService.Captured dayEvidence(){return day.evidence();}
        @Override public String toString(){return "CapturedCatalogDayAnalysisInput[redacted]";}
    }
    private final Object issuer=new Object();private final String category;private final CatalogDayAnalysisCommitPermitService original;
    private final CatalogDayAnalysisReservationLedger reservations;private final CatalogEntityAnalysisHeaderService headers;private final EntityInputEvidenceService current;
    private final FrozenSourceStagePlanService plans;private final CatalogVersionJudgmentLedger judgments;private final JdbcFrozenSourcePlans owners;private final JdbcJobRecords records;
    private final CatalogAnalysisContentBaselineService contents;private final CatalogPreviousAnalysisService previous;private final JdbcCatalogVersionJobFacts oldJobs;private final TransactionTemplate reads;
    public CatalogDayAnalysisInputPermitService(CatalogDayAnalysisCommitPermitService original,CatalogDayAnalysisReservationLedger reservations,
            CatalogEntityAnalysisHeaderService headers,EntityInputEvidenceService current,FrozenSourceStagePlanService plans,CatalogVersionJudgmentLedger judgments,
            JdbcFrozenSourcePlans owners,JdbcJobRecords records,CatalogAnalysisContentBaselineService contents,CatalogPreviousAnalysisService previous,
            JdbcCatalogVersionJobFacts oldJobs,PlatformTransactionManager manager,String category){
        this.original=Objects.requireNonNull(original);this.reservations=Objects.requireNonNull(reservations);this.headers=Objects.requireNonNull(headers);this.current=Objects.requireNonNull(current);this.plans=Objects.requireNonNull(plans);this.judgments=Objects.requireNonNull(judgments);this.owners=Objects.requireNonNull(owners);this.records=Objects.requireNonNull(records);this.contents=Objects.requireNonNull(contents);this.previous=Objects.requireNonNull(previous);this.oldJobs=Objects.requireNonNull(oldJobs);this.category=switch(Objects.requireNonNull(category)){case "agent","skill","workflow","model"->category;default->throw invalid();};reads=new TransactionTemplate(Objects.requireNonNull(manager));reads.setReadOnly(true);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);
    }
    public Captured capture(LocalDate day,String entity){
        if(TransactionSynchronizationManager.isActualTransactionActive())throw invalid();WireValues.id(entity,false);var full=original.captureOriginal(Objects.requireNonNull(day));if(full==null)throw invalid();
        return Objects.requireNonNull(reads.execute(s->{var state=state(full.evidence(),entity,false);JdbcCatalogVersionJobFacts.Snapshot jobs=null;
            if(!state.origins().isEmpty()){
                var origin=CanonicalJson.parse(state.origins().getFirst());var nativePrevious=previous.readInSnapshot(category,entity,state.target()).orElseThrow(CatalogDayAnalysisInputPermitService::invalid);var profile=CatalogPreviousVersionProfile.read(CatalogPreviousAnalysisEvidence.read(nativePrevious).orElseThrow(CatalogDayAnalysisInputPermitService::invalid)).orElseThrow(CatalogDayAnalysisInputPermitService::invalid);
                if(!profile.proofJson().equals(JdbcFrozenInputs.canonical(origin.get("previous_proof")))||!nativePrevious.rootId().equals(text(origin,"root_id"))||nativePrevious.generation()!=number(origin,"generation")||!nativePrevious.inputHash().equals(text(origin,"input_hash"))||!nativePrevious.resultHash().equals(text(origin,"result_hash")))throw invalid();jobs=oldJobs.capture(text(origin,"root_id"),text(origin,"claim_target_hash"));
            }return new Captured(issuer,full,state,jobs);
        }));
    }
    /** Holds original source/day, receipt, current entity/member, pending intent and complete old result/content locks. */
    public Captured verify(Captured captured){
        JdbcFrozenInputs.requireTx();if(!Integer.valueOf(TransactionDefinition.ISOLATION_READ_COMMITTED).equals(TransactionSynchronizationManager.getCurrentTransactionIsolationLevel())||captured==null||captured.issuer!=issuer)throw invalid();var day=original.verify(captured.day);var fresh=state(day,captured.receipt().entityId(),true);
        if(!same(captured.state,fresh))throw invalid();if(captured.oldJobs!=null&&!captured.oldJobs.equals(oldJobs.lockAndRead(captured.oldJobs.root(),captured.oldJobs.claimTargetHash())))throw invalid();
        var receipt=fresh.receipt();if(!receipt.intentId().equals(records.ensureIntent(new JdbcJobRecords.Intent(receipt.intentId(),receipt.logicalKey(),receipt.generation(),category+"_analysis",receipt.day()),receipt.reservedAt())))throw invalid();
        var expected=new TreeMap<String,CatalogDayEntityEvidenceService.Evidence>();for(var member:fresh.entity().members())if(expected.putIfAbsent(member.member().itemId(),member)!=null)throw invalid();var values=current.read(receipt.entityId(),category,expected.keySet(),day.original().cutoff());if(values.entityRevision()!=fresh.header().revision()||values.members().size()!=expected.size())throw invalid();for(var member:values.members()){var old=expected.remove(member.id());if(old==null||member.revision()!=old.member().revision()||!member.category().equals(category)||!member.identityKey().equals(old.identityKey())||!member.title().equals(old.title())||!Objects.equals(member.summary(),old.summary())||!member.payloadJson().equals(old.bodyJson()))throw invalid();}if(!expected.isEmpty())throw invalid();return captured;
    }
    private State state(CatalogDayEntityEvidenceService.Captured day,String entity,boolean writer){
        if(!category.equals(day.original().category()))throw invalid();var receipt=writer?reservations.lockAndRead(day.original().day(),entity):reservations.read(day.original().day(),entity);if(receipt==null||!category.equals(receipt.category())||!receipt.closureHash().equals(day.original().closureHash())||!receipt.groupingHash().equals(day.grouping().hash()))throw invalid();
        var group=day.entities().stream().filter(value->entity.equals(value.entityId())).findFirst().orElseThrow(CatalogDayAnalysisInputPermitService::invalid);if(group.members().size()>100||!receipt.members().equals(members(group)))throw invalid();var header=(writer?headers.lockInWriter(Set.of(entity)):headers.findInSnapshot(Set.of(entity))).get(entity);var raw=CanonicalJson.parse(receipt.json());if(header==null||!header.category().equals(category)||!header.identityHash().equals(text(raw,"entity_identity_hash"))||header.generation()!=receipt.generation()||!"queued".equals(header.state())||header.revision()<receipt.entityRevisionAfter())throw invalid();
        var intent=writer?owners.lockOwner(receipt.intentId()):owners.immutableOwner(receipt.intentId());if(!"generation_intent".equals(intent.kind())||!receipt.logicalKey().equals(intent.key())||!Arrays.equals(JdbcGenerationLineage.hash(receipt.logicalKey()),intent.keyHash())||intent.generation()!=receipt.generation()||!(category+"_analysis").equals(intent.type())||!receipt.day().equals(intent.businessDate())||!"waiting_input".equals(intent.state())||(writer?owners.hasRoots(receipt.intentId()):owners.immutableHasRoots(receipt.intentId())))throw invalid();
        var snapshots=new HashMap<String,JsonNode>();var decisions=new HashMap<String,String>();for(var source:day.original().sources()){var result=CanonicalJson.parse(source.result().json());var reference=FrozenSourceStagePlan.Reference.fromJson(JdbcFrozenInputs.canonical(result.get("plan_ref")));var plan=writer?plans.read(reference):plans.readImmutable(reference);for(var chunk:plan.chunks())snapshots.put(chunk.rootId(),CanonicalJson.parse(chunk.snapshotJson()));for(var fragment:result.get("stage_result").get("fragments"))for(var item:fragment.get("payload").get("items"))decisions.put(WireValues.id(item.get("item_id"),false),text(item,"decision"));}
        var recorded=new TreeMap<String,String>();var origins=new TreeMap<String,String>();for(var member:group.members()){
            if(!"existing".equals(decisions.get(member.member().itemId())))continue;var snapshot=Objects.requireNonNull(snapshots.get(member.member().rootId()));var input=FrozenApplicationContext.fromJson(snapshot.get(FrozenApplicationContext.FIELD)).input(member.member().rootId(),"catalog-analysis-input-qualification",member.inputHash(),0);if(!"2".equals(input.dedupResultVersion()))continue;var projection=FrozenCatalogVersionProjections.read(snapshot.get(FrozenCatalogVersionProjections.FIELD),input).entries().get(member.member().itemId());if(projection==null)continue;if(!entity.equals(projection.entityId()))throw invalid();var judgment=(writer?judgments.lockAndRead(projection.judgmentKey()):judgments.read(projection.judgmentKey())).orElseThrow(CatalogDayAnalysisInputPermitService::invalid);var p=CanonicalJson.parse(projection.json());var value=CanonicalJson.parse(judgment.json()).get("judgment_value");if(!entity.equals(judgment.entityId())||!category.equals(judgment.category())||judgment.recordedAt().isAfter(day.original().cutoff())||!text(p.get("current_proof"),"version_hash").equals(text(value,"version_hash"))||!text(p.get("current_proof"),"qualification_hash").equals(text(value,"qualification_hash")))throw invalid();recorded.put(judgment.judgmentKey(),judgment.json());if("reanalyze".equals(judgment.verdict())&&judgment.generation()==receipt.generation()&&receipt.intentId().equals(judgment.intentId()))origins.put(projection.itemId(),projection.json());
        }
        String target;if("new_entity".equals(receipt.trigger())){if(!origins.isEmpty())throw invalid();target=CatalogAnalysisContentBaselineService.newContentId(category,entity);}else{if(origins.isEmpty())throw invalid();target=text(CanonicalJson.parse(origins.firstEntry().getValue()),"content_id");}
        var baseline=writer?contents.lockInWriter(entity,target):contents.findInSnapshot(entity,target);if(origins.isEmpty()){if(baseline!=null)throw invalid();}else{if(baseline==null)throw invalid();var first=CanonicalJson.parse(origins.firstEntry().getValue());for(String json:origins.values()){var origin=CanonicalJson.parse(json);if(!target.equals(text(origin,"content_id"))||!baseline.inputRoot().equals(text(origin,"root_id"))||baseline.bodyRevision()!=number(origin,"content_body_revision")||!baseline.bodyHash().equals(text(origin,"content_body_hash"))||baseline.revision()<number(origin,"content_revision"))throw invalid();for(String field:List.of("root_id","claim_target_hash","input_hash","result_hash","generation","previous_proof"))if(!origin.get(field).equals(first.get(field)))throw invalid();}}
        return new State(receipt,group,header,target,baseline,List.copyOf(recorded.values()),List.copyOf(origins.values()));
    }
    private static List<CatalogDayAnalysisReservationLedger.Member> members(CatalogDayEntityEvidenceService.Entity entity){return entity.members().stream().sorted(Comparator.comparing(m->m.member().itemId())).map(value->{var m=value.member();return new CatalogDayAnalysisReservationLedger.Member(m.itemId(),m.runId(),m.sourceId(),m.rootId(),value.inputHash(),value.bodyHash(),m.fragmentResultHash(),m.finalResultHash(),m.revision());}).toList();}
    private static boolean same(State first,State second){return first.receipt().json().equals(second.receipt().json())&&first.entity().equals(second.entity())&&first.header().equals(second.header())&&first.target().equals(second.target())&&Objects.equals(first.baseline(),second.baseline())&&first.judgments().equals(second.judgments())&&first.origins().equals(second.origins());}
    private static String text(JsonNode node,String field){return WireValues.text(node.get(field));}private static long number(JsonNode node,String field){return WireValues.nonnegativeInteger(node.get(field));}
    private static IllegalStateException invalid(){return new IllegalStateException("allocated original catalog day analysis input permission unavailable");}
}
